import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9c2c2');scene.fog=new THREE.FogExp2('#9cb4b7',.009);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.08,380);camera.position.set(0,1.68,5.5);camera.rotation.order='YXZ';
const hemi=new THREE.HemisphereLight('#d7eff2','#5a4438',1.45);scene.add(hemi);
const sun=new THREE.DirectionalLight('#ffe3b4',3.3);sun.position.set(-45,65,35);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;sun.shadow.bias=-.00015;scene.add(sun);
const fill=new THREE.DirectionalLight('#80a9c3',.8);fill.position.set(30,18,-35);scene.add(fill);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const dustMat=mat('#a8896d',.98), rockMat=mat('#675c54',1), darkMetal=mat('#263538',.52,.68), lightMetal=mat('#aebbb4',.38,.66), orange=mat('#d9894b',.5,.38), glass=new THREE.MeshPhysicalMaterial({color:'#82c7ca',metalness:.18,roughness:.13,transparent:true,opacity:.46,clearcoat:1}), glow=new THREE.MeshBasicMaterial({color:'#85ffe0'});

// A wide procedural, tessellated alien desert.
const terrainGeo=new THREE.PlaneGeometry(360,360,180,180);terrainGeo.rotateX(-Math.PI/2);const pos=terrainGeo.attributes.position;const colors=[];
function noise(x,z){return Math.sin(x*.17+Math.sin(z*.11)*1.4)*.43+Math.cos(z*.23+x*.08)*.27+Math.sin((x+z)*.48)*.09+Math.cos(x*.052-z*.071)*.68;}
for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),n=noise(x,z);pos.setY(i,n*1.05);const c=new THREE.Color(n>.5?'#b9a184':n<-.45?'#655f59':'#93816d');c.offsetHSL(0,0,(Math.random()-.5)*.045);colors.push(c.r,c.g,c.b)}terrainGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));terrainGeo.computeVertexNormals();const terrain=new THREE.Mesh(terrainGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));terrain.receiveShadow=true;scene.add(terrain);
function groundY(x,z){return noise(x,z)*1.05}
// atmospheric haze backdrop and tiny stars
const starsGeo=new THREE.BufferGeometry(),starPos=[];for(let i=0;i<950;i++){const r=130+Math.random()*90,theta=Math.random()*Math.PI*2,phi=Math.random()*Math.PI;starPos.push(r*Math.sin(phi)*Math.cos(theta),r*Math.cos(phi),r*Math.sin(phi)*Math.sin(theta))}starsGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPos,3));scene.add(new THREE.Points(starsGeo,new THREE.PointsMaterial({color:'#e4eee8',size:.42,transparent:true,opacity:.68,sizeAttenuation:false})));
const sunDisc=new THREE.Mesh(new THREE.SphereGeometry(5,32,24),new THREE.MeshBasicMaterial({color:'#ffe7bd'}));sunDisc.position.set(-68,47,-130);scene.add(sunDisc);
const planet=new THREE.Mesh(new THREE.SphereGeometry(9,48,32),new THREE.MeshStandardMaterial({color:'#536c72',roughness:1}));planet.position.set(70,49,-180);scene.add(planet);
const planetGlow=new THREE.Mesh(new THREE.SphereGeometry(9.15,32,24),new THREE.MeshBasicMaterial({color:'#98c8cc',transparent:true,opacity:.12,side:THREE.BackSide}));planet.add(planetGlow);

const world=new THREE.Group();scene.add(world);const interactables=[];const deposits=[];
function addMesh(parent,geometry,material,x,y,z,opts={}){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=opts.cast!==false;m.receiveShadow=true;if(opts.rx)m.rotation.x=opts.rx;if(opts.ry)m.rotation.y=opts.ry;if(opts.rz)m.rotation.z=opts.rz;parent.add(m);return m}
function cylinder(parent,r1,r2,h,material,x,y,z,segments=12){return addMesh(parent,new THREE.CylinderGeometry(r1,r2,h,segments),material,x,y,z)}
function makePad(x,z,r=2.1){const y=groundY(x,z)+.045;const pad=addMesh(world,new THREE.CylinderGeometry(r,r,.12,48),mat('#48514a',.84,.12),x,y,z);const ring=addMesh(world,new THREE.TorusGeometry(r-.12,.035,6,64),new THREE.MeshBasicMaterial({color:'#84d9c6'}),x,y+.09,z);ring.rotation.x=Math.PI/2;for(let i=0;i<4;i++){const a=i*Math.PI/2;addMesh(world,new THREE.BoxGeometry(.13,.04,.48),orange,x+Math.cos(a)*(r-.12),y+.08,z+Math.sin(a)*(r-.12),{ry:-a})}return {x,z,r,y}}
const pads=[makePad(-5,-7,2.1),makePad(3,-8,2.2),makePad(9,-3,2)];
// Detailed, deliberately readable starter habitat.
function makeHabitat(x,z){const g=new THREE.Group();g.position.set(x,groundY(x,z),z);world.add(g);
 addMesh(g,new THREE.CylinderGeometry(1.25,1.42,1.7,16),lightMetal,0,1.05,0);addMesh(g,new THREE.CylinderGeometry(1.27,1.27,.13,16),darkMetal,0,.24,0);addMesh(g,new THREE.CylinderGeometry(1.22,1.22,.13,16),darkMetal,0,1.86,0);
 const dome=addMesh(g,new THREE.SphereGeometry(1.23,24,16,0,Math.PI*2,0,Math.PI/2),glass,0,1.87,0);dome.scale.y=.7;
 for(let i=0;i<8;i++){const a=i*Math.PI/4;const rib=addMesh(g,new THREE.BoxGeometry(.045,1.55,.055),lightMetal,Math.cos(a)*1.24,1.05,Math.sin(a)*1.24,{ry:-a});}
 for(let i=0;i<4;i++){const a=i*Math.PI/2;addMesh(g,new THREE.BoxGeometry(.16,.42,.14),orange,Math.cos(a)*1.29,.95,Math.sin(a)*1.29,{ry:-a})}
 const door=addMesh(g,new THREE.BoxGeometry(.62,.95,.12),darkMetal,0,.65,1.25);addMesh(g,new THREE.BoxGeometry(.42,.7,.03),glass,0,.7,1.33);addMesh(g,new THREE.BoxGeometry(.11,.08,.08),glow,.25,.68,1.38);
 cylinder(g,.22,.28,.6,darkMetal,-1.37,.28,0);cylinder(g,.14,.14,.1,orange,-1.37,.58,0);const antenna=addMesh(g,new THREE.CylinderGeometry(.025,.025,1.9,8),lightMetal,.55,2.55,-.4);addMesh(g,new THREE.SphereGeometry(.12,12,8),glow,.55,3.52,-.4);
 const light= new THREE.PointLight('#73f3d0',3,6);light.position.set(0,2,1.5);g.add(light);
 const sign=addMesh(g,new THREE.BoxGeometry(.7,.22,.035),darkMetal,0,2.22,1.02);const led=addMesh(g,new THREE.BoxGeometry(.42,.025,.02),glow,0,2.23,1.05);
 return g}
makeHabitat(-5,-7);
// Landing vehicle / shuttle with functional construction point.
function makeLander(x,z){const g=new THREE.Group();g.position.set(x,groundY(x,z),z);world.add(g);addMesh(g,new THREE.CylinderGeometry(.65,.85,1.55,8),lightMetal,0,1.35,0);addMesh(g,new THREE.ConeGeometry(.65,.65,8),orange,0,2.45,0);addMesh(g,new THREE.CylinderGeometry(.87,.87,.18,12),darkMetal,0,.52,0);for(let i=0;i<4;i++){let a=i*Math.PI/2+.4;const lx=Math.cos(a),lz=Math.sin(a);addMesh(g,new THREE.BoxGeometry(.12,.95,.13),lightMetal,lx*.72,.42,lz*.72,{rz:lx*.2,rx:-lz*.2});addMesh(g,new THREE.BoxGeometry(.63,.12,.3),darkMetal,lx*1.05,.08,lz*1.05,{ry:-a});}const win=addMesh(g,new THREE.SphereGeometry(.39,16,12),glass,0,1.65,.55);win.scale.set(1,.7,.28);for(let i=-1;i<=1;i++)addMesh(g,new THREE.BoxGeometry(.12,.07,.07),glow,i*.25,.54,.79);return g}
makeLander(9,-3);
// Solar panel module, articulated and striped with visible photovoltaic cells.
function makeSolar(x,z,active=false){const g=new THREE.Group();g.position.set(x,groundY(x,z),z);world.add(g);cylinder(g,.15,.23,.55,darkMetal,0,.33,0);addMesh(g,new THREE.BoxGeometry(.18,.1,.18),orange,0,.61,0);for(const side of [-1,1]){const panel=addMesh(g,new THREE.BoxGeometry(1.35,.055,1.03),mat('#22404d',.3,.55),side*1.05,.85,0,{rz:side*.08});for(let j=0;j<4;j++)addMesh(g,new THREE.BoxGeometry(.012,.012,.96),mat('#73aeb6',.4,.4),side*1.05+(j-1.5)*.31,.883,0);for(let j=0;j<3;j++)addMesh(g,new THREE.BoxGeometry(1.28,.012,.012),mat('#73aeb6',.4,.4),side*1.05,.883,(j-1)*.31);addMesh(g,new THREE.BoxGeometry(.08,.15,.08),lightMetal,side*.4,.65,0)}return g}
makeSolar(3,-8,false);
// Distant ridges and clustered boulders to give the horizon real scale.
for(let i=0;i<95;i++){let x=(Math.random()-.5)*95,z=-13-Math.random()*75,s=.35+Math.random()*2.2;let b=addMesh(world,new THREE.DodecahedronGeometry(s,1),i%4?rockMat:mat('#8c7560'),x,groundY(x,z)+s*.42,z,{ry:Math.random()*3});b.scale.y=.48+Math.random()*.55}
for(let i=0;i<24;i++){let x=(Math.random()-.5)*135,z=-42-Math.random()*45,h=4+Math.random()*15;let geo=new THREE.ConeGeometry(5+Math.random()*6,h,5);const m=addMesh(world,geo,mat(i%2?'#8f9e9c':'#869696'),x,groundY(x,z)+h*.44,z,{ry:Math.random()*6.2});m.scale.z=.8+Math.random()*.5}
// Minerals are clustered in the walkable foreground, animated with a soft beacon.
function makeDeposit(x,z,type='ore'){const g=new THREE.Group();g.position.set(x,groundY(x,z),z);world.add(g);const isIce=type==='ice', crystalMat=isIce?new THREE.MeshStandardMaterial({color:'#8ed8eb',roughness:.25,metalness:.18,emissive:'#24617b',emissiveIntensity:.42}):new THREE.MeshStandardMaterial({color:'#dc995e',roughness:.35,metalness:.24,emissive:'#6d3518',emissiveIntensity:.25});for(let i=0;i<5;i++){const h=.55+Math.random()*.85;let c=addMesh(g,new THREE.OctahedronGeometry(.34+Math.random()*.18,0),crystalMat,(Math.random()-.5)*.8,h*.43,(Math.random()-.5)*.65,{ry:Math.random()*3,rz:(Math.random()-.5)*.4});c.scale.y=1.2+Math.random()*.7}const ring=addMesh(g,new THREE.TorusGeometry(.8,.018,5,32),new THREE.MeshBasicMaterial({color:isIce?'#77d9f2':'#f1b878',transparent:true,opacity:.65}),0,.08,0);ring.rotation.x=Math.PI/2;const beam=addMesh(g,new THREE.CylinderGeometry(.015,.38,2.5,12,1,true),new THREE.MeshBasicMaterial({color:isIce?'#76daf2':'#e6ae6e',transparent:true,opacity:.09,side:THREE.DoubleSide}),0,1.55,0,{cast:false});const hit=addMesh(g,new THREE.SphereGeometry(1.05,10,8),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}),0,.65,0,{cast:false});hit.userData={type:'deposit',deposit:g,resType:type,active:true};interactables.push(hit);g.userData={kind:'deposit',resType:type,active:true,phase:Math.random()*6};deposits.push(g);return g}
makeDeposit(1.5,1.7,'ore');makeDeposit(-3.2,-1.2,'ice');makeDeposit(5.5,-2.2,'ore');makeDeposit(-8.2,2.5,'ore');makeDeposit(8,3.5,'ice');
// Starter waypoint lights and surveyed perimeter.
const perimeter=new THREE.Group();world.add(perimeter);const points=[[-13,-14],[13,-14],[13,5],[-13,5]];for(let i=0;i<4;i++){const [x,z]=points[i], [nx,nz]=points[(i+1)%4];const line=addMesh(perimeter,new THREE.BoxGeometry(.035,.035,Math.hypot(nx-x,nz-z)),new THREE.MeshBasicMaterial({color:'#6bd4bd',transparent:true,opacity:.35}),(x+nx)/2,groundY((x+nx)/2,(z+nz)/2)+.08,(z+nz)/2,{ry:Math.atan2(nx-x,nz-z),cast:false});for(let j=0;j<5;j++){const t=j/5,px=x+(nx-x)*t,pz=z+(nz-z)*t;addMesh(perimeter,new THREE.SphereGeometry(.055,8,6),glow,px,groundY(px,pz)+.14,pz,{cast:false})}}

let state={ferrite:120,ice:48,power:86,miners:0,solars:0,habitats:1,harvested:0};try{const saved=JSON.parse(localStorage.getItem('frontier-save'));if(saved)state={...state,...saved}}catch{}
function save(){localStorage.setItem('frontier-save',JSON.stringify(state))}
const $=s=>document.querySelector(s);let msgTimer;function message(text){const n=$('#notification');n.textContent=text;n.classList.add('show');clearTimeout(msgTimer);msgTimer=setTimeout(()=>n.classList.remove('show'),2100)}
function notify(title,sub){const t=$('#toast');t.querySelector('b').textContent=title;t.querySelector('small').textContent=sub;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function refresh(){ $('#ferrite').textContent=Math.floor(state.ferrite);$('#ice').textContent=Math.floor(state.ice);$('#power').textContent=Math.floor(state.power);$('#income').textContent='+'+(state.miners*12);$('#objective-fill').style.width=state.miners?'100%':'0%';$('#objective-text').textContent=`${state.miners} / 1 structures online`; }
refresh();
const buildDock=$('#build-dock');let placing=null;function openBuild(){buildDock.classList.add('open');document.exitPointerLock?.();}function closeBuild(){buildDock.classList.remove('open');placing=null;}
$('#close-dock').onclick=closeBuild;document.querySelectorAll('.build-card').forEach(button=>button.addEventListener('click',()=>{const type=button.dataset.build;const cost={miner:[80,0,30],solar:[60,0,0],habitat:[100,20,0]}[type];if(state.ferrite<cost[0]||state.ice<cost[1]||state.power<cost[2]){message('INSUFFICIENT RESOURCES — mine nearby deposits');return}const avail=pads.find(p=>!p.occupied);if(!avail){message('ALL PERIMETER PADS OCCUPIED');return}avail.occupied=true;state.ferrite-=cost[0];state.ice-=cost[1];state.power-=cost[2];if(type==='miner'){state.miners++;buildMiner(avail.x,avail.z);notify('MINER ONLINE','Ferrite extraction +12 kg / min')}else if(type==='solar'){state.solars++;makeSolar(avail.x,avail.z,true);notify('SOLAR ARRAY ONLINE','Power generation +18 kWh / min')}else{state.habitats++;makeHabitat(avail.x,avail.z);notify('HABITAT POD DEPLOYED','Crew capacity expanded')}refresh();save();closeBuild()}));
function buildMiner(x,z){const g=new THREE.Group();g.position.set(x,groundY(x,z),z);world.add(g);addMesh(g,new THREE.BoxGeometry(1.15,.85,.85),darkMetal,0,.6,0);addMesh(g,new THREE.BoxGeometry(.8,.52,.56),lightMetal,0,1.28,-.05);cylinder(g,.2,.26,.44,orange,0,1.55,-.05);const drill=addMesh(g,new THREE.ConeGeometry(.3,.72,8),lightMetal,0,.12,-.58,{rx:Math.PI});addMesh(g,new THREE.BoxGeometry(.12,1.25,.12),darkMetal,-.45,1.1,-.38,{rz:-.4});addMesh(g,new THREE.BoxGeometry(.12,1.25,.12),darkMetal,.45,1.1,-.38,{rz:.4});for(let i=-1;i<=1;i++)addMesh(g,new THREE.BoxGeometry(.22,.07,.16),glow,i*.3,.65,.44);const lamp=new THREE.PointLight('#71f2cd',2,5);lamp.position.set(0,1.6,.6);g.add(lamp);g.userData.drill=drill;g.userData.kind='miner';miners.push(g)}
const miners=[];let lastTick=performance.now();setInterval(()=>{const dt=(performance.now()-lastTick)/60000;lastTick=performance.now();if(state.miners){const produced=state.miners*12*dt;state.ferrite+=produced;state.power=Math.max(0,state.power-state.miners*5*dt+state.solars*18*dt);refresh();save()}else if(state.solars){state.power=Math.min(999,state.power+state.solars*18*dt);refresh();save()}},1000);

// First-person locomotion, pointer-look, mining and E interaction.
const keys={};let yaw=0,pitch=-.04,locked=false,started=false;const raycaster=new THREE.Raycaster();raycaster.far=9;const center=new THREE.Vector2(0,0);function castCenter(){raycaster.setFromCamera(center,camera);return raycaster.intersectObjects(interactables,false)[0]}
function updateTarget(){const hit=castCenter(),hint=$('#interaction-hint'),label=$('#scan-label');if(hit?.object.userData.active){hint.classList.add('show');label.textContent=hit.object.userData.resType==='ice'?'WATER ICE DEPOSIT':'FERRITE VEIN';label.style.color=hit.object.userData.resType==='ice'?'#9ed8e8':'#e4b176'}else{hint.classList.remove('show');label.textContent='OUTPOST PERIMETER';label.style.color='rgba(220,238,232,.62)'}}
function harvest(hit){const d=hit.object.userData,group=d.deposit;if(!d.active)return;d.active=false;group.userData.active=false;group.visible=false;const amount=d.resType==='ice'?12:18;if(d.resType==='ice')state.ice+=amount;else state.ferrite+=amount;state.harvested++;refresh();save();notify(d.resType==='ice'?'WATER ICE SECURED':'FERRITE HARVESTED',`+${amount} ${d.resType==='ice'?'L water ice':'kg ferrite'}`);setTimeout(()=>{d.active=true;group.userData.active=true;group.visible=true},12500)}
function interact(){const hit=castCenter();if(hit?.object.userData.active)harvest(hit);else if(!buildDock.classList.contains('open'))openBuild()}
canvas.addEventListener('click',e=>{if(!started)return;if(buildDock.classList.contains('open'))return;if(!locked){canvas.requestPointerLock?.();return}interact()});document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===canvas});document.addEventListener('mousemove',e=>{if(!locked)return;yaw-=e.movementX*.0022;pitch-=e.movementY*.0019;pitch=Math.max(-1.35,Math.min(1.25,pitch));camera.rotation.set(pitch,yaw,0)});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyB')buildDock.classList.contains('open')?closeBuild():openBuild();if(e.code==='KeyE')interact();if(e.code==='KeyJ')message('FIELD JOURNAL — Expedition log updated');if(e.code==='Escape')closeBuild()});window.addEventListener('keyup',e=>keys[e.code]=false);
$('#begin-btn').onclick=()=>{$('#modal-backdrop').classList.add('hidden');started=true;message('EXPEDITION LIVE — Click the terrain to look around')};$('#help-toggle').onclick=()=>$('#modal-backdrop').classList.remove('hidden');$('#modal-close').onclick=()=>{$('#modal-backdrop').classList.add('hidden');started=true};$('#journal-toggle').onclick=()=>message(`FIELD LOG — ${state.harvested} deposits harvested · ${state.miners} miners online`);$('#sound-toggle').onclick=e=>{e.currentTarget.textContent=e.currentTarget.textContent==='♫'?'♪':'♫';message('AMBIENT AUDIO IS MUTED')};

const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05),t=clock.elapsedTime;for(const d of deposits){if(d.visible){d.rotation.y+=dt*.15;d.children.forEach((c,i)=>{if(i<5)c.position.y=(.55+(i%3)*.17)+Math.sin(t*1.4+i)*.045});}}
 for(const m of miners){m.userData.drill.rotation.y+=dt*2.7;}if(started&&!buildDock.classList.contains('open')){const f=(keys.ShiftLeft||keys.ShiftRight)?8:4.7;const forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0);const side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);if(forward||side){const v=new THREE.Vector3(Math.sin(yaw)*forward+Math.cos(yaw)*side,0,-Math.cos(yaw)*forward+Math.sin(yaw)*side).normalize().multiplyScalar(f*dt);camera.position.x+=v.x;camera.position.z+=v.z;camera.position.x=THREE.MathUtils.clamp(camera.position.x,-24,24);camera.position.z=THREE.MathUtils.clamp(camera.position.z,-30,18);camera.position.y=groundY(camera.position.x,camera.position.z)+1.68+Math.sin(t*9)*.025}}
 updateTarget();renderer.render(scene,camera)}animate();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});

